SELECT
cm.financing_customer_id,
cm.dealer_id,
cm.dealer_manager_id,
cm.tax_data,
cm.address,
cm.comments,
cm.dealership_name ,
cm.reference_code,
cm.documents,
DATETIME(cm.created_at, cmt.country_timezone) as created_at,
DATETIME(cm.updated_at, cmt.country_timezone) as updated_at,
DATETIME(cm.deleted_at, cmt.country_timezone) as deleted_at,
cm.created_by_name,
cm.created_by_id,
cm.updated_by_name,
cm.updated_by_id,
cm.deleted_by_name,
cm.deleted_by_id,
cm.risk_score,
cm.internal_id,
cm.email,
cm.phone,
TRIM(cm.country_id) as country_id,
cm.manual_freeze_reason,
cm.manual_freeze_comments,
cm.is_manual_freeze,
cm.first_name,
cm.last_name,
cm.financial_status,
cm.delivery_blocking,
cm.bidding_blocking,
cm.checkout_blocking,
cm.credit_blocking
FROM `{{params.project_name}}.staging.FinancingCustomers` cm
INNER JOIN `{{params.project_name}}.staging.CountryMetadata` cmt on TRIM(cm.country_id) = cmt.country_id
WHERE cm.updated_at >= '{{params.start_ts}}' AND cm.updated_at < '{{params.end_ts}}'